import { describe, it, expect, beforeAll, afterAll } from "vitest";
import { readFileSync, readdirSync } from "node:fs";
import { createHash } from "node:crypto";
import { dirname, join } from "node:path";
import { inWordList, resetWordListCache } from "./wordlist";
import { installAppOrigin } from "./eval/headless/origin";

// public/wordlist/ is generated by scripts/build-wordlist.mjs from the installed word-list package.
const OUT = join(process.cwd(), "public", "wordlist");
const meta = JSON.parse(readFileSync(join(OUT, "meta.json"), "utf8")) as { version: string; sha256: string; words: number; shardKeys: string[] };
const original = globalThis.fetch;

describe("the bundled English word list", () => {
  beforeAll(() => { resetWordListCache(); installAppOrigin(); });
  afterAll(() => { globalThis.fetch = original; resetWordListCache(); });

  it("holds every word of the installed package's words.txt, at the pinned version and hash", async () => {
    const pkg = dirname((await import("word-list")).default);
    const raw = readFileSync(join(pkg, "words.txt"));
    expect(JSON.parse(readFileSync(join(pkg, "package.json"), "utf8")).version).toBe(meta.version);
    expect(createHash("sha256").update(raw).digest("hex")).toBe(meta.sha256);
    const words = raw.toString("utf8").split("\n").filter(Boolean);
    const shards = readdirSync(OUT).filter((f) => /^[a-z]{2}\.json$/.test(f)).map((f) => f.slice(0, 2)).sort();
    expect(shards).toEqual(meta.shardKeys);
    const shipped = shards.flatMap((k) => (JSON.parse(readFileSync(join(OUT, `${k}.json`), "utf8")) as string).split(" "));
    expect(shipped).toEqual(words);
    expect(meta.words).toBe(words.length);
    expect(readFileSync(join(OUT, "LICENSE"), "utf8")).toBe(readFileSync(join(pkg, "license"), "utf8"));
  });

  it("answers through the app's fetch path: real words WordNet lacks, and not a misspelling", async () => {
    for (const w of ["chalcogens", "granivore", "voltammeter", "skeleton"]) expect(await inWordList(w), w).toBe(true);
    for (const w of ["skelitin", "qzx", "a", "Skeleton", ""]) expect(await inWordList(w), w).toBe(false);
  });
});
